require("windowrules")
require("autostart")
require("popups")
-- candy.lua is GENERATED by candy.py from ~/.config/bubble-candy/tokens.json,
-- and its own header documents that it is sourced from here. It was never
-- required, so the whole generated Hyprland half of the design system was dead
-- config. Loaded FIRST so the explicit values further down this file remain the
-- final word; what was actually missing is its border colours
-- (general.col.active_border / inactive_border) and its extra animation leaves.
require("candy")

local mainMod = "SUPER"

-- ============================================================
-- MONITOR
-- ============================================================

hl.monitor({
  output   = "DP-1",
  -- 120Hz on purpose, NOT 144Hz.
  --   143.998 / 60 = 2.40   and  / 30 = 4.80  -> neither divides evenly
  --   119.98  / 60 = 2.00   and  / 30 = 4.00  -> both exact
  -- A refresh rate that is not an integer multiple of the video frame rate is
  -- the classic cause of the browser "dropped frames" counter climbing on
  -- 144Hz panels. This monitor offers 1920x1080@119.98Hz.
  mode     = "1920x1080@120",
  position = "auto",
  scale    = 1,
  vrr      = 3,
})

-- ============================================================
-- GENERAL + APPEARANCE
-- ============================================================

hl.config({
  general = {
    gaps_in     = 2,
    gaps_out    = 8,
    border_size = 0,
    -- col = {
    --     active_border   = "rgb(2a9ff5)",
    --     inactive_border = "rgba(2a9ff566)",
    -- },
    layout      = "dwindle",
  },

  cursor = {
    -- Hardware cursors ON. With software cursors Hyprland reported
    --   directScanoutBlockedBy: windowed mode,software renders/cursors,...
    -- and had to recomposite the full frame on every cursor move. That is a
    -- classic Hyprland/NVIDIA stutter source. If you see cursor corruption or
    -- a laggy pointer, flip this back to true (it was the old workaround).
    no_hardware_cursors = false,
  },

  decoration = {
    rounding         = 20,
    -- 1.0 keeps windows OPAQUE, which lets Hyprland take the fast, non-blended
    -- render path. Anything below 1.0 forces an alpha blend of the whole window
    -- every frame and also blocks direct scanout. Terminals opt back in to 0.9
    -- explicitly via windowrules.lua.
    active_opacity   = 1.0,
    inactive_opacity = 1.0,
    shadow           = {
      enabled      = true,
      range        = 22,
      render_power = 3,
      offset       = { 0, 7 },
      color        = "rgba(1a1a1a59)",
    },
    blur             = {
      enabled  = true,
      size     = 3,
      passes   = 1,
      vibrancy = 0.1696,
    },
  },

  misc = {
    force_default_wallpaper = 0,
    disable_hyprland_logo   = true,
    background_color        = "rgba(0,0,0,0)",
    middle_click_paste      = false,
  },

  render = {
    direct_scanout = 2,
  },

  input = {
    kb_layout     = "br",
    kb_variant    = "abnt2",
    kb_options    = "",
    repeat_delay  = 600,
    repeat_rate   = 25,
    follow_mouse  = 1,
    accel_profile = "flat",
    touchpad      = {
      natural_scroll = true,
      tap_to_click   = true,
    },
  },

  animations = {
    enabled = true,
  },
})

hl.animation({ leaf = "windows", enabled = true, speed = 5, bezier = "default" })

-- Troca de workspace: fade rápido de entrada/saída, em vez do slide lento.
-- Sem uma leaf explícita, workspaces herda a `global` (speed 8, sem estilo),
-- que é exatamente o slide que incomodava. speed é a DURAÇÃO (menor = mais
-- rápido): 8 -> 2. O style "fade" é o mesmo que o default do Hyprland usa.
hl.animation({ leaf = "workspaces", enabled = true, speed = 2, bezier = "default", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 2, bezier = "default", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 2, bezier = "default", style = "fade" })

-- ============================================================
-- BUBBLE CANDY SURFACES: never compositor-animated
-- ============================================================
-- The dashboard and the control centre are not popups that appear: they are
-- blobs that grow out of the bar, and their geometry animates inside a
-- fixed-size surface. Hyprland's default layersIn/layersOut fade cross-fades
-- the whole surface as it maps/unmaps, which reads as the panel "fading in"
-- over the top of the growth and destroys the illusion. Measured on a glyph
-- pixel inside the dashboard: 209 -> 44 over ~500 ms with the default, and it
-- snaps straight to 44 with no_anim. The shell animates these itself.
--
-- The match is an RE2 regex over the WHOLE namespace (Hyprland's LayerRule does a
-- FullMatch), so the alternation that used to be here covered the panels and nothing
-- else: `bubble-candy-bar`, `bubble-candy-frame` and `bubble-candy-field` did not match
-- it and kept the animation. That is what made going fullscreen look broken — the bar
-- unmaps, and candy.lua's `layersIn/layersOut = slide` slid it (and the full-screen
-- field) out, so for ~0.5s the bar's CONTENT was in place over an unpainted top strip
-- while the whole frame slid. A prefix pattern covers every surface the shell owns,
-- now and later.
hl.layer_rule({ match = { namespace = "bubble-candy-.*" }, no_anim = true })

-- `wayfreeze` is the fullscreen freeze the screenshot script paints before `slurp`
-- runs. Same story, same slide, and a frozen frame that slides in is worse than one
-- that is simply there: it moves the very region the user is about to select.
hl.layer_rule({ match = { namespace = "wayfreeze" }, no_anim = true })

-- `slurp` is the second half of that same script, and its layer-shell namespace is
-- `selection`, NOT `slurp` (slurp-1.5.0 main.c: get_layer_surface(..., "selection")).
-- So the rule above never covered it and the selection overlay still slid in.
-- slurp paints its whole output with the translucent background before it draws the
-- selection, so candy.lua's layersIn slide dimmed the screen by sliding the dim in
-- on top of the frozen frame — the exact animation the rule above was meant to kill.
-- Match the namespace the tool actually uses, not its binary name.
hl.layer_rule({ match = { namespace = "selection" }, no_anim = true })

-- ============================================================
-- MOUSE
-- ============================================================

hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- ============================================================
-- WINDOW MANAGEMENT
-- ============================================================

-- Float moved to SUPER+D to free SUPER+SPACE for the launcher (see below)
-- and SHIFT+SPACE for shifted app shortcuts.
hl.bind(mainMod .. " + D", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" })) -- niri fullscreen-window
hl.bind(mainMod .. " + R", hl.dsp.layout("togglesplit"))                      -- ~ niri switch-preset-column-width
hl.bind(mainMod .. " + C", hl.dsp.layout("splitratio 0.5"))                   -- ~ niri center-column

hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }))

-- ============================================================
-- LAUNCHERS + APPS
-- ============================================================

hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("ghostty"))
-- The app menu is Bubble Candy's own launcher (modules/launcher/), asked for over
-- Quickshell's IPC. Rofi is retired: a second process that draws a second material
-- was never going to match the shell it opens over.
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd("qs ipc call shell toggleLauncher"))

-- Boba: the mode-driven launcher. One keybind shape for every mode —
-- `qs ipc call boba <verb> <mode>` — so a new mode is a line here plus a row in
-- services/Boba.qml's mode table, never a new IPC function.
--
-- SUPER+SPACE is the app list, which is what a launcher key should do by habit.
-- The prefix modes are also reachable without any keybind by typing `=` or `%`.
-- `Super+Return` above still opens the OLD launcher until Boba's Home mode exists
-- (M5); when it does, that line becomes `boba open home` and modules/launcher/ goes.
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("qs ipc call boba open apps"))
hl.bind(mainMod .. " + X", hl.dsp.exec_cmd("qs ipc call boba toggle calc"))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("qs ipc call boba toggle clip"))
hl.bind(mainMod .. " + TAB", hl.dsp.exec_cmd("qs ipc call boba toggle win"))
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("qs ipc call boba toggle notif"))
-- The session menu replaces a bare `Super+Shift+E` -> hl.dsp.exit(). Nothing here
-- fires on one press: Log out, Restart and Shut down arm on the first Enter and run
-- on the second (LAUNCHER.md §6).
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("qs ipc call boba toggle power"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("dolphin"))
hl.bind(mainMod .. " + ALT + L", hl.dsp.exec_cmd("hyprlock"))

-- Hourly chime at every XX:00 — Super+Alt+H toggles it on/off.
-- The timing itself lives in the systemd user timer (hourly-chime.timer), so
-- this bind only flips the switch; `hourly-chime status` prints the next fire.
hl.bind(mainMod .. " + ALT + H", hl.dsp.exec_cmd("/home/cesar/.local/bin/hourly-chime toggle"))

-- ============================================================
